components.css:
.ds-btn-primary { display: inline-flex; align-items: center; justify-content: center; min-height: 48px; padding: 0.65rem 1.2rem; border-radius: 999px; background: var(--paper-bright); color: var(--ink); font-family: "Schibsted Grotesk", "Avenir Next", "Segoe UI", sans-serif; font-size: 1.0625rem; font-weight: 600; letter-spacing: -0.02em; line-height: 1.2; text-decoration: none; }
.ds-btn-primary:hover { background: #ffffff; }
.ds-btn-primary:focus-visible { outline: 2px solid var(--thread); outline-offset: 3px; }

.ds-btn-field { display: inline-flex; align-items: center; justify-content: center; min-height: 48px; padding: 0.65rem 1.2rem; border-radius: 999px; background: var(--field); color: var(--paper-bright); font-family: "Schibsted Grotesk", "Avenir Next", "Segoe UI", sans-serif; font-size: 1.0625rem; font-weight: 600; letter-spacing: -0.02em; line-height: 1.2; text-decoration: none; }
.ds-btn-field:hover { background: var(--field-deep); }
.ds-btn-field:focus-visible { outline: 2px solid var(--field); outline-offset: 3px; }

.ds-toggle-stage { display: inline-block; background: var(--field); padding: 0.7rem 1rem; }
.ds-nav-toggle { appearance: none; background: transparent; color: var(--paper-bright); border: 1px solid var(--line-light); border-radius: 999px; min-height: 44px; padding: 0.35rem 0.95rem; font-family: "Schibsted Grotesk", "Avenir Next", "Segoe UI", sans-serif; font-size: 1.0625rem; font-weight: 560; cursor: pointer; }
.ds-nav-toggle:hover { border-color: var(--thread); color: var(--thread); }
.ds-nav-toggle:focus-visible { outline: 2px solid var(--thread); outline-offset: 3px; }

.ds-mast { background: var(--field); color: var(--paper-bright); font-family: "Schibsted Grotesk", "Avenir Next", "Segoe UI", sans-serif; }
.ds-mast-thread { height: 3px; background: var(--thread); }
.ds-mast-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem 1.35rem; min-height: 4.25rem; padding: 0.7rem 1rem; }
.ds-wordmark { display: flex; flex-direction: column; gap: 0.1rem; margin-right: auto; color: inherit; text-decoration: none; line-height: 1.15; }
.ds-wordmark-name { font-size: 1.05rem; font-weight: 650; letter-spacing: -0.03em; }
.ds-wordmark-place { font-size: 0.9375rem; color: var(--mist); }
.ds-nav { display: flex; align-items: center; gap: 1.35rem; }
.ds-nav a { color: inherit; text-decoration: none; font-size: 1rem; font-weight: 500; min-height: 44px; display: inline-flex; align-items: center; }
.ds-nav a:not(.ds-nav-hire):hover { color: var(--thread); }
.ds-nav a:focus-visible { outline: 2px solid var(--thread); outline-offset: 3px; }
.ds-nav a.ds-nav-hire { min-height: 48px; padding: 0.65rem 1.2rem; border-radius: 999px; background: var(--paper-bright); color: var(--ink); font-size: 1.05rem; font-weight: 600; letter-spacing: -0.02em; line-height: 1.2; }
.ds-nav a.ds-nav-hire:hover { background: #ffffff; color: var(--ink); }

.ds-link-row { display: flex; flex-wrap: wrap; align-items: center; gap: 1.35rem; font-family: "Schibsted Grotesk", "Avenir Next", "Segoe UI", sans-serif; }
.ds-text-link { color: var(--ink); font-weight: 600; letter-spacing: -0.02em; text-underline-offset: 0.22em; font-size: 1.0625rem; }
.ds-text-link:focus-visible { outline: 2px solid var(--field); outline-offset: 3px; }
.ds-field-link { background: var(--field); padding: 0.35rem 0.7rem; }
.ds-text-link-field { color: var(--paper-bright); text-decoration-color: var(--thread); }
.ds-text-link-field:focus-visible { outline-color: var(--thread); }

.ds-browser { background: var(--paper-bright); color: var(--ink); border-radius: 14px 14px 0 0; overflow: hidden; box-shadow: 0 22px 44px rgba(8, 24, 28, 0.28); font-family: "Schibsted Grotesk", "Avenir Next", "Segoe UI", sans-serif; }
.ds-browser-bar { display: flex; align-items: center; gap: 0.4rem; padding: 0.7rem 0.9rem; background: var(--paper); }
.ds-browser-bar span:nth-child(-n + 3) { width: 0.5rem; height: 0.5rem; border-radius: 50%; background: #8aa0a3; flex: none; }
.ds-browser-url { margin-left: 0.45rem; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 0.875rem; color: var(--ink-soft); }
.ds-browser-view { height: 8.5rem; background: var(--mist); }

.ds-service { padding: 1.15rem 0 1.25rem; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); font-family: "Schibsted Grotesk", "Avenir Next", "Segoe UI", sans-serif; color: var(--ink); max-width: 62ch; }
.ds-service-title { font-size: clamp(1.4rem, 2vw, 1.8rem); font-weight: 560; letter-spacing: -0.03em; line-height: 1.15; }
.ds-service p { margin: 0.4rem 0 0; color: var(--ink-soft); font-size: 1.0625rem; font-weight: 450; line-height: 1.55; }

.ds-process { position: relative; background: var(--field); color: var(--paper-bright); padding: 0.25rem 1rem; font-family: "Schibsted Grotesk", "Avenir Next", "Segoe UI", sans-serif; }
.ds-rail { position: absolute; left: 1rem; top: 0; bottom: 0; width: 3px; background: var(--line-light); }
.ds-rail-fill { display: block; width: 100%; height: 100%; background: var(--thread); }
.ds-steps { list-style: none; margin: 0; padding: 0; counter-reset: step; }
.ds-steps li { counter-increment: step; padding: 1.7rem 0 1.35rem 1.35rem; }
.ds-steps h3 { margin: 0 0 0.45rem; font-size: clamp(1.45rem, 2vw, 1.85rem); font-weight: 560; letter-spacing: -0.03em; line-height: 1.05; color: var(--paper-bright); }
.ds-steps h3::before { content: counter(step); margin-right: 0.45em; color: var(--thread); }
.ds-steps p { margin: 0; max-width: 62ch; color: var(--mist); font-size: 1.0625rem; font-weight: 450; line-height: 1.55; }
.ds-steps a:focus-visible, .ds-process :focus-visible { outline: 2px solid var(--thread); outline-offset: 3px; }
